import type { Metadata } from "next";
import { Poppins } from "next/font/google"; // Import font Poppins
import "./globals.css";

// Konfigurasi Font Poppins dengan variasi ketebalan yang kita butuhkan
const poppins = Poppins({
  subsets: ["latin"],
  weight: ["300", "400", "500", "600", "700"],
  variable: "--font-poppins",
});

export const metadata: Metadata = {
  title: "Firman Damai Zebua | Software Developer",
  description: "Portfolio website of Firman Damai Zebua, S.Kom. - Software Developer & Full-Stack Engineer",
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <html lang="en" className={`dark scroll-smooth ${poppins.variable}`}>
      <body className={`${poppins.className} bg-[#09090B] text-[#FAFAFA] antialiased`}>
        {children}
      </body>
    </html>
  );
}